def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of arguments
        """
        # Helper conversion functions
        def to_bool(val):
            if isinstance(val, str):
                lowered = val.lower()
                if lowered in ("true", "t", "yes", "1"):
                    return True
                if lowered in ("false", "f", "no", "0"):
                    return False
            return val

        def to_number(val):
            if isinstance(val, str):
                try:
                    if '.' in val or 'e' in val.lower():
                        return float(val)
                    return int(val)
                except ValueError:
                    pass
            return val

        # Iterate over all key/value pairs and attempt to cast them
        for key, value in list(values_dict.items()):
            if isinstance(value, str):
                # Try boolean conversion first
                bool_val = to_bool(value)
                if bool_val is not value:
                    values_dict[key] = bool_val
                    continue
                # Try numeric conversion
                num_val = to_number(value)
                if num_val is not value:
                    values_dict[key] = num_val
        # No return needed as values_dict is modified in place

